 let(mut p,mut scene,view,vm,mut profiler,controls):Saved=sims_fixtures::Store::open(std::env::var_os("SIMS_DIAG_INPUT_STORE").map(PathBuf::from).unwrap_or_else(||root.join("fixtures/private/goth-diagonal-endpoint-20261101-first/cold-third.store")))?.get_value(&input)?;
 let source=std::fs::read(root.join("fixtures/private/goth-level-geometry-20261101-first/geometry-source-first.json"))?;let setup=std::fs::read(root.join("fixtures/private/goth-geometry-first-vector-20261101-first/first-vector-source-first.json"))?;
