 let mut rows=vec![];let mut c4_inner=vec![];let mut in_c4=false;for line in BufReader::new(flate2::read::GzDecoder::new(native.as_slice())).lines(){let q:serde_json::Value=serde_json::from_str(&line?)?;if q["trace_stop"].as_u64().is_some_and(|n|n<start_stop){continue}let Some(pc)=q["pc"].as_u64()else{continue};if pc==0x4c79ca&&q["corner_ordinal"].is_number(){in_c4=true;}else if pc==0x53ca46{in_c4=false;}else if in_c4{c4_inner.push(serde_json::json!({"pc":pc,"trace_stop":q["trace_stop"],"corner_ordinal":q["corner_ordinal"]}));continue;}if q["kind"]=="world_drawing_setup"&&((0x53c250..=0x53ca56).contains(&pc)||matches!(pc,0x53c227|0x5404a7|0x4ad2d9)||(q["corner_ordinal"].is_number()&&matches!(pc,0x4c79ca|0x4c8849|0x4c8878|0x4c8884|0x4c88a0|0x4c88ac|0x4c88d4|0x4c8910|0x4c89f9|0x4c9e38|0x4c8a79|0x4c8aab|0x4b444f|0x4b4456|0x49f2a3|0x4c8afa))){rows.push(q);}}
